    private fun huge(name: String, vararg parts: String): ImageVector =
        ImageVector.Builder("Hugeicons.$name", 24.dp, 24.dp, 24f, 24f).apply {
            parts.forEach { part ->
                val head = part.substringBefore('|')
                val mode = head.first()
                val alpha = head.substringAfter('@', "1").toFloat()
                addPath(
                    PathParser().parsePathString(part.substringAfter('|')).toNodes(),
                    fill = if (mode == 'F' || mode == 'B') SolidColor(Color.White) else null,
                    fillAlpha = alpha,
                    stroke = if (mode == 'S' || mode == 'B') SolidColor(Color.White) else null,
                    strokeAlpha = alpha,
                    strokeLineWidth = 1.5f,
                    strokeLineCap = StrokeCap.Round,
                    strokeLineJoin = StrokeJoin.Round
                )
            }
        }.build()
}
